import jakarta.persistence.*;
import java.util.*;
@Entity class Task{@Id @GeneratedValue Long id;String text;protected Task(){}Task(String t){text=t;}}
public class JpaRemove{public static void main(String[]a){EntityManager em=MiniJpa.open();for(String t:List.of("a","b","c"))em.persist(new Task(t));long id=new Scanner(System.in).nextLong();List<Task> before=em.createQuery("SELECT t FROM Task t",Task.class).getResultList();Task found=em.find(Task.class,id);if(found!=null)em.remove(found);List<Task> after=em.createQuery("SELECT t FROM Task t",Task.class).getResultList();System.out.println("before="+before.size()+" after="+after.size());}}

