import java.util.*;
class Document{int version;String text;Document(int v,String t){version=v;text=t;}boolean update(int expected,String next){if(version!=expected)return false;text=next;version++;return true;}}
public class JpaVersion{public static void main(String[]a){Scanner s=new Scanner(System.in);Document d=new Document(s.nextInt(),"old");int expected=s.nextInt();if(d.update(expected,"new"))System.out.println("更新 version="+d.version);else System.out.println("競合: 再読込してください");}}
